<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }

 $t=$id?one('SELECT * FROM '.table('testimonials').' WHERE id=?',[$id]):[];if($id&&!$t){echo '<div class="notice error">Testimonial not found.</div>';admin_foot();exit;}$t=$t?:['name'=>'','role'=>'','quote'=>'','rating'=>5,'sort_order'=>0,'published'=>0,'consent'=>0];?><form class="admin-card editor-single" method="post" action="<?=esc(admin_url('testimonial',['id'=>$id]))?>"><?php admin_action('testimonial_save');?><input type="hidden" name="id" value="<?=$id?>"><div class="field-grid"><?php admin_input('name','Client name',$t['name'],'text','required maxlength="120"');admin_input('role','Business / role',$t['role'],'text','maxlength="160"');?></div><?php admin_textarea('quote','Genuine client quotation',$t['quote'],6,3000);?><div class="field-grid"><?php admin_select('rating','Rating',[5=>'5 stars',4=>'4 stars',3=>'3 stars',2=>'2 stars',1=>'1 star'],$t['rating']);admin_input('sort_order','Display order',$t['sort_order'],'number','min="-9999" max="9999"');?></div><?php admin_check('consent','This is genuine feedback and I have permission to publish it.',$t['consent']);admin_check('published','Publish on the homepage',$t['published']);?><button class="btn gold">Save Testimonial →</button></form><?php if($id):?><form class="delete-form" method="post" action="<?=esc(admin_url('testimonial',['id'=>$id]))?>" data-confirm="Permanently delete this testimonial?"><?php admin_action('testimonial_delete');?><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger small">Delete Testimonial</button></form><?php endif;
